#!/bin/sh
# clean-coverage.sh — remove test coverage reports under a root.
# Coverage is regenerated by npm test --coverage / pytest --cov.
set -eu
DIR=$(dirname "$0")
# shellcheck source-path=SCRIPTDIR/lib source=cleanup.sh
. "$DIR/lib/cleanup.sh"

usage() {
	cat <<EOF
usage: clean-coverage.sh [--apply] [root]
  remove coverage, htmlcov, nyc_output, .nyc_output and .coverage.
  Default: dry-run; tracked paths are skipped.
EOF
}

init_cleanup "coverage reports" "$@"

find "$ROOT" \
	\( -name .git -o -name node_modules -o -name '.venv*' -o -name venv \) -prune -o \
	\( -name coverage -o -name htmlcov -o -name nyc_output -o -name .nyc_output \) \
	-type d -print -prune -o \
	-name .coverage -type f -print \
	>"$TMPF" 2>/dev/null || true

each_candidate
report
